begin;
do $$
declare a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();sport uuid;tid uuid;mid uuid;child uuid;rules jsonb:='[{"unit":"legs","first_to":6,"winner_points":10,"exact_points":15},{"unit":"legs","first_to":6,"winner_points":10,"exact_points":15}]';before_row jsonb;
begin
 if to_regclass('auth.users') is not null then
  insert into auth.users(id,email,email_confirmed_at,aud,role) values(a,a||'@recovery-qa.invalid',now(),'authenticated','authenticated'),(u,u||'@recovery-qa.invalid',now(),'authenticated','authenticated');
  insert into public.profiles(id,username) values(a,'rq-'||substr(a::text,1,20)),(u,'rq-'||substr(u::text,1,20)) on conflict do nothing;
 end if;
 insert into public.user_roles values(a,'admin'),(u,'user');select id into sport from public.sports where slug='darts';
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('role','authenticated',true);
 tid:=public.create_knockout_game('QA recovery',sport,'players',array['QA A','QA B','QA C'],now()+interval '1 day',rules,'replacement',now()+interval '3 days','draft');
 perform public.manage_tournament(tid,'metadata',jsonb_build_object('name','QA recovery renamed','start',now()+interval '1 day','end',now()+interval '3 days'));
 perform set_config('role','none',true);
 select match_id into mid from predict_private.knockout_nodes where tournament_id=tid and round_no=1 and not is_bye;
 select match_id into child from predict_private.knockout_nodes where tournament_id=tid and round_no=2;
 perform set_config('role','authenticated',true);
 perform public.edit_knockout(tid,'schedule',mid,jsonb_build_object('start',now()+interval '1 day','unit','legs','first_to',6));
 perform public.edit_knockout(tid,'schedule',child,jsonb_build_object('start',now()+interval '2 days','unit','legs','first_to',6));
 perform public.edit_knockout(tid,'publish');
 perform set_config('request.jwt.claim.sub',u::text,true);perform public.join_tournament(tid);perform public.submit_match_prediction(mid,6,3);
 begin perform public.edit_knockout(tid,'undo_postpone',mid);raise exception 'FAIL user recovery';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',a::text,true);perform public.edit_knockout(tid,'postpone',mid);
 perform set_config('role','none',true);update public.matches set scheduled_start=now()-interval '1 hour' where id=mid;perform set_config('role','authenticated',true);
 perform public.edit_knockout(tid,'undo_postpone',mid);
 perform set_config('role','none',true);
 if (select status<>'scheduled' or predictions_enabled from public.matches where id=mid) then raise exception 'FAIL undo postponement';end if;
 perform set_config('role','authenticated',true);
 perform public.edit_knockout(tid,'result',mid,'{"home_score":6,"away_score":3}');
 if (select earned_points from public.get_tournament_leaderboard(tid) where user_id=u)<>15 then raise exception 'FAIL initial points';end if;
 perform public.edit_knockout(tid,'reset_result',mid);
 if (select earned_points from public.get_tournament_leaderboard(tid) where user_id=u)<>0 then raise exception 'FAIL reset points';end if;
 perform set_config('role','none',true);
 if (select home_score is not null or away_score is not null or actual_start is not null or status<>'scheduled' or predictions_enabled from public.matches where id=mid) then raise exception 'FAIL reset';end if;
 if (select winner_slot is not null from predict_private.knockout_nodes where match_id=mid) or (select home_slot is not null and away_slot is not null from predict_private.knockout_nodes where match_id=child) then raise exception 'FAIL advancement remains';end if;
 if not exists(select 1 from public.match_predictions where match_id=mid and user_id=u and home_score=6 and away_score=3) then raise exception 'FAIL prediction lost';end if;
 perform set_config('role','authenticated',true);
 perform public.edit_knockout(tid,'result',mid,'{"home_score":6,"away_score":3}');
 perform set_config('request.jwt.claim.sub',u::text,true);perform public.submit_match_prediction(child,6,3);perform set_config('request.jwt.claim.sub',a::text,true);
 begin perform public.edit_knockout(tid,'reset_result',mid);raise exception 'FAIL downstream predictions lost';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 perform set_config('role','none',true);
 if (select home_score<>6 or status<>'finished' from public.matches where id=mid) then raise exception 'FAIL non-atomic reset';end if;
 delete from public.match_predictions where match_id=child;
 update public.matches set predictions_enabled=false,actual_start=now(),status='live' where id=child;
 perform set_config('role','authenticated',true);
 begin perform public.edit_knockout(tid,'reset_result',mid);raise exception 'FAIL started downstream reset';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 perform public.edit_knockout(tid,'result',mid,'{"home_score":6,"away_score":2}');
 perform set_config('role','none',true);
 if not exists(select 1 from public.match_audit_log where match_id=mid and action='knockout_reset_result') then raise exception 'FAIL missing audit';end if;
end $$;
rollback;
